int a; // a 는 좌측값
int& l_a = a; // l_a 는 좌측값 레퍼런스
int& r_b = 3; // 3 은 우측값. 따라서 오류
여태까지 우리가 다루어왔던 레퍼런스는 ’좌측값’ 에만 레퍼런스를 가질 수 있습니다. 예를 들어서,
a 의 경우 좌측값 이기 때문에, a 의 좌측값 레퍼런스인 l_a 를 만들 수 있습니다.
반면에 3 의 경우 우측값이기 때문에, 우측값의 레퍼런스인 r_b 를 만들 수 없습니다. 따라서 이
문장은 오류가 발생하게 됩니다.
이와 같이 & 하나를 이용해서 정의하는 레퍼런스를 좌측값 레퍼런스 (lvalue reference) 라고
부르고, 좌측값 레퍼런스 자체도 좌측값이 됩니다.
그럼 다른 예제를 살펴보도록 합시다.
int& func1(int& a) { return a; }
int func2(int b) { return b; }
int main() {
int a = 3;
func1(a) = 4;
std::cout << &func1(a) << std::endl;
int b = 2;
a = func2(b); // 가능
func2(b) = 5; // 오류 1
std::cout << &func2(b) << std::endl; // 오류 2
}
